/**
 * Wall 최소 수직/수평 철근
 * KDS 14 20 50  (metric, threshold 400 MPa)
 * ACI 318-19 Table 11.6.1  (imperial, threshold 420 MPa)
 */

const MM_TO_IN = 0.03937;

/**
 * @param {object} p
 * @param {number} p.h_mm         벽체 두께 (mm)
 * @param {number} p.fy_mpa       항복강도 (MPa)
 * @param {Array}  p.rebarMetric
 * @param {Array}  p.rebarImperial
 * @returns {{ metric, imperial }}
 */
export function calcWallReinf({ h_mm, fy_mpa, rebarMetric, rebarImperial }) {
  if (h_mm <= 0 || fy_mpa <= 0) return null;

  // ── KDS 14 20 50  (임계값 400 MPa) ──
  let rho_l_ks, rho_t_ks;
  if (fy_mpa <= 400) {
    rho_l_ks = 0.0015; rho_t_ks = 0.0025;
  } else {
    rho_l_ks = 0.0012; rho_t_ks = 0.0020;
  }
  const As_l_mm = rho_l_ks * 1000 * h_mm;
  const As_t_mm = rho_t_ks * 1000 * h_mm;

  // ── ACI 318-19 Table 11.6.1  (임계값 420 MPa) ──
  let rho_l_aci, rho_t_aci;
  if (fy_mpa < 420) {
    rho_l_aci = 0.0015; rho_t_aci = 0.0025;
  } else {
    rho_l_aci = 0.0012; rho_t_aci = 0.0020;
  }
  const h_in = h_mm * MM_TO_IN;
  const As_l_in = rho_l_aci * 12 * h_in;
  const As_t_in = rho_t_aci * 12 * h_in;

  return {
    metric: {
      rho_l: rho_l_ks, rho_t: rho_t_ks,
      As_l: As_l_mm, As_t: As_t_mm,
      rebars: rebarMetric.map(bar => ({
        name: bar.name,
        s_l: (bar.area_mm2 * 1000) / As_l_mm,
        s_t: (bar.area_mm2 * 1000) / As_t_mm,
      })),
    },
    imperial: {
      rho_l: rho_l_aci, rho_t: rho_t_aci,
      As_l: As_l_in, As_t: As_t_in,
      rebars: rebarImperial.map(bar => ({
        name: bar.name,
        s_l: (bar.area_in2 * 12) / As_l_in,
        s_t: (bar.area_in2 * 12) / As_t_in,
      })),
    },
  };
}
