import { useState, useMemo } from 'react'
import UnitInput from '../../components/shared/UnitInput'
import FySelect from '../../components/shared/FySelect'
import ResultBox from '../../components/shared/ResultBox'
import RebarSpacingList from '../../components/shared/RebarSpacingList'
import { calcWallReinf } from '../../engines/wallReinf'

const REBAR_METRIC   = [
  { name: 'D10', area_mm2: 71.3 }, { name: 'D13', area_mm2: 126.7 },
  { name: 'D16', area_mm2: 198.6 }, { name: 'D19', area_mm2: 284.9 },
  { name: 'D22', area_mm2: 387.1 }, { name: 'D25', area_mm2: 506.7 },
]
const REBAR_IMPERIAL = [
  { name: '#3', area_in2: 0.11 }, { name: '#4', area_in2: 0.20 },
  { name: '#5', area_in2: 0.31 }, { name: '#6', area_in2: 0.44 },
  { name: '#7', area_in2: 0.60 }, { name: '#8', area_in2: 0.79 },
]
const MM_TO_IN = 0.03937

export default function WallView() {
  const [h_mm,   setH]   = useState('200')
  const [fy_mpa, setFy]  = useState(400)
  const [layer,  setLayer] = useState('single')  // 'single' | 'double'

  const result = useMemo(() =>
    calcWallReinf({
      h_mm: parseFloat(h_mm) || 0,
      fy_mpa,
      rebarMetric: REBAR_METRIC,
      rebarImperial: REBAR_IMPERIAL,
    }), [h_mm, fy_mpa]
  )

  const layerFactor = layer === 'double' ? 2 : 1

  return (
    <div>
      <h3 style={titleStyle}>WALL — Min. Vertical &amp; Horizontal Reinforcement</h3>
      <p style={descStyle}>KDS 14 20 50 (threshold 400 MPa) / ACI 318-19 Table 11.6.1 (threshold 420 MPa)</p>

      {/* Single / Double toggle */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 20, alignItems: 'center' }}>
        {[{ id: 'single', label: 'SINGLE' }, { id: 'double', label: 'DOUBLE' }].map(opt => (
          <button key={opt.id} onClick={() => setLayer(opt.id)} style={{
            padding: '6px 18px', borderRadius: 6, fontSize: 12, fontWeight: 600, cursor: 'pointer',
            border: '1px solid var(--bd-subtle)',
            background: layer === opt.id ? 'var(--ac-main)' : 'var(--bg-card)',
            color: layer === opt.id ? '#000' : 'var(--tx-secondary)',
          }}>{opt.label}</button>
        ))}
        {layer === 'double' && (
          <span style={{ fontSize: 11, color: 'var(--tx-muted)' }}>
            Each curtain = As,min / 2 → spacing × 2
          </span>
        )}
      </div>

      <div className="grid md:grid-cols-2 gap-8">
        {/* KS */}
        <div style={cardKS}>
          <h4 style={{ fontSize: 14, fontWeight: 700, marginBottom: 14, color: 'var(--ac-main)' }}>🇰🇷 KS CODE (METRIC)</h4>
          <UnitInput id="wall-h-mm" label="Wall Thickness h" unit="mm" value={h_mm} onChange={setH} />
          <div style={{ marginBottom: 16 }}>
            <label style={labelStyle}>Steel Yield Strength fy</label>
            <FySelect fy_mpa={fy_mpa} onChange={setFy} />
          </div>
          {result && (
            <ResultBox title={`Min. Reinforcement — ${layer === 'double' ? 'DOUBLE (per curtain)' : 'SINGLE'} (KDS)`} accent>
              <p style={rowStyle}>
                Vertical ρl = {result.metric.rho_l} →
                As = <Val>{(result.metric.As_l / layerFactor).toFixed(0)} mm²/m</Val>
                {layer === 'double' && <span style={note}> (total: {result.metric.As_l.toFixed(0)})</span>}
              </p>
              <p style={rowStyle}>
                Horiz. ρt = {result.metric.rho_t} →
                As = <Val>{(result.metric.As_t / layerFactor).toFixed(0)} mm²/m</Val>
                {layer === 'double' && <span style={note}> (total: {result.metric.As_t.toFixed(0)})</span>}
              </p>
              <SubLabel>D-Bar Spacing V/H (mm){layer === 'double' ? ' per curtain' : ''}</SubLabel>
              <RebarSpacingList
                items={result.metric.rebars.map(r => ({
                  name: r.name,
                  s_l: r.s_l * layerFactor,
                  s_t: r.s_t * layerFactor,
                }))}
                unit="mm"
              />
            </ResultBox>
          )}
        </div>

        {/* ACI */}
        <div style={cardACI}>
          <h4 style={{ fontSize: 14, fontWeight: 700, marginBottom: 14, color: 'var(--tx-primary)' }}>🇺🇸 ACI CODE (IMPERIAL)</h4>
          <UnitInput id="wall-h-in" label="Wall Thickness h" unit="in"
            value={h_mm ? (parseFloat(h_mm) * MM_TO_IN).toFixed(2) : ''}
            onChange={v => setH((parseFloat(v) / MM_TO_IN).toFixed(1))} />
          <div style={{ marginBottom: 16 }}>
            <label style={labelStyle}>Steel Yield Strength fy</label>
            <FySelect fy_mpa={fy_mpa} onChange={setFy} />
          </div>
          {result && (
            <ResultBox title={`Required Min. Steel — ${layer === 'double' ? 'DOUBLE (per curtain)' : 'SINGLE'} (ACI)`}>
              <p style={rowStyle}>
                Vertical ρl = {result.imperial.rho_l} →
                As = <Val>{(result.imperial.As_l / layerFactor).toFixed(3)} in²/ft</Val>
                {layer === 'double' && <span style={note}> (total: {result.imperial.As_l.toFixed(3)})</span>}
              </p>
              <p style={rowStyle}>
                Horiz. ρt = {result.imperial.rho_t} →
                As = <Val>{(result.imperial.As_t / layerFactor).toFixed(3)} in²/ft</Val>
                {layer === 'double' && <span style={note}> (total: {result.imperial.As_t.toFixed(3)})</span>}
              </p>
              <SubLabel>Bar Spacing V/H (in){layer === 'double' ? ' per curtain' : ''}</SubLabel>
              <RebarSpacingList
                items={result.imperial.rebars.map(r => ({
                  name: r.name,
                  s_l: r.s_l * layerFactor,
                  s_t: r.s_t * layerFactor,
                }))}
                unit="in"
              />
            </ResultBox>
          )}
        </div>
      </div>
    </div>
  )
}

function Val({ children }) {
  return <span style={{ fontWeight: 700, color: 'var(--val-pos)' }}>{children}</span>
}
function SubLabel({ children }) {
  return <h5 style={{ fontSize: 11, fontWeight: 600, color: 'var(--tx-secondary)', marginTop: 12, marginBottom: 6, paddingTop: 10, borderTop: '1px solid var(--bd-subtle)' }}>{children}</h5>
}

const titleStyle = { fontSize: '1.3rem', fontWeight: 700, marginBottom: 8, color: 'var(--tx-primary)', paddingBottom: 10, borderBottom: '1px solid var(--bd-subtle)' }
const descStyle  = { marginBottom: 20, color: 'var(--tx-secondary)', fontSize: 13 }
const rowStyle   = { fontSize: 13, color: 'var(--tx-primary)', marginBottom: 6 }
const labelStyle = { display: 'block', fontSize: 12, fontWeight: 500, color: 'var(--tx-secondary)', marginBottom: 4 }
const note       = { fontSize: 11, color: 'var(--tx-muted)', marginLeft: 6 }
const cardBase = { background: 'var(--bg-card)', border: '1px solid', borderRadius: 10, padding: 20 }
const cardKS   = { ...cardBase, borderColor: 'var(--bd-accent)' }
const cardACI  = { ...cardBase, borderColor: 'var(--bd-muted)' }
